import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './AdminProducts.css';

function AdminProducts() {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [editData, setEditData] = useState({});
  const [message, setMessage] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [newProduct, setNewProduct] = useState({
    name: '',
    price: '',
    unit: '',
    category_id: '',
    estoque: ''
  });
  const [imageFile, setImageFile] = useState(null);
  const [showNewForm, setShowNewForm] = useState(false);

  const API_URL = 'http://localhost:3001/api';

  useEffect(() => {
    fetchProducts();
    fetchCategories();
  }, []);

  const fetchProducts = async () => {
    try {
      const response = await axios.get(`${API_URL}/products`);
      setProducts(response.data);
    } catch (error) {
      console.error('Erro ao buscar produtos:', error);
    }
  };

  const fetchCategories = async () => {
    try {
      const response = await axios.get(`${API_URL}/categories`);
      setCategories(response.data);
    } catch (error) {
      console.error('Erro ao buscar categorias:', error);
    }
  };

  // 🔍 FILTRO
  const filteredProducts = products.filter(product => {
    const matchesSearch = product.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = filterCategory === '' || product.category_id === parseInt(filterCategory);
    return matchesSearch && matchesCategory;
  });

  // 📊 STATS
  const lowStockCount = products.filter(p => p.estoque > 0 && p.estoque <= 10).length;
  const outOfStockCount = products.filter(p => p.estoque === 0).length;

  const getCategoryName = (categoryId) => {
    const cat = categories.find(c => c.id === categoryId);
    return cat ? cat.name : 'Sem categoria';
  };

  const getStockStatus = (estoque) => {
    if (estoque > 10) return { icon: '🟢', text: 'OK', color: '#22c55e' };
    if (estoque > 0) return { icon: '🟡', text: 'BAIXO', color: '#f59e0b' };
    return { icon: '🔴', text: 'VAZIO', color: '#ef4444' };
  };

  const startEdit = (product) => {
    setEditingId(product.id);
    setEditData({ ...product });
  };

  const saveEdit = async () => {
    try {
      if (!editData.name || !editData.price || !editData.unit || !editData.category_id) {
        setMessage('❌ Preencha todos os campos');
        return;
      }

      const token = localStorage.getItem('authToken');
      
      // Atualizar produto básico
      await axios.put(`${API_URL}/products/${editingId}`, {
        name: editData.name,
        price: parseFloat(editData.price),
        unit: editData.unit,
        category_id: parseInt(editData.category_id)
      }, {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      // Atualizar estoque separadamente
      if (editData.estoque !== undefined) {
        await axios.put(`${API_URL}/products/${editingId}/estoque`, {
          estoque: parseInt(editData.estoque)
        }, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
      }

      setMessage('✅ Produto atualizado com sucesso!');
      setEditingId(null);
      fetchProducts();
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      setMessage('❌ Erro ao atualizar produto');
      console.error(error);
    }
  };

  const createProduct = async () => {
    try {
      if (!newProduct.name || !newProduct.price || !newProduct.unit || !newProduct.category_id) {
        setMessage('❌ Preencha todos os campos obrigatórios');
        return;
      }

      const formData = new FormData();
      formData.append('name', newProduct.name);
      formData.append('price', parseFloat(newProduct.price));
      formData.append('unit', newProduct.unit);
      formData.append('category_id', parseInt(newProduct.category_id));
      formData.append('estoque', parseInt(newProduct.estoque || 0));
      if (imageFile) {
        formData.append('image', imageFile);
      }

      const token = localStorage.getItem('authToken');
      await axios.post(`${API_URL}/products`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
          'Authorization': `Bearer ${token}`
        }
      });

      setMessage('✅ Produto criado com sucesso!');
      setNewProduct({ name: '', price: '', unit: '', category_id: '', estoque: '' });
      setImageFile(null);
      setShowNewForm(false);
      fetchProducts();
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      setMessage('❌ Erro ao criar produto');
      console.error(error);
    }
  };

  const deleteProduct = async (id) => {
    if (window.confirm('Tem certeza que deseja deletar este produto?')) {
      try {
        const token = localStorage.getItem('authToken');
        await axios.delete(`${API_URL}/products/${id}`, {
          headers: { 'Authorization': `Bearer ${token}` }
        });
        setMessage('✅ Produto deletado com sucesso!');
        fetchProducts();
        setTimeout(() => setMessage(''), 3000);
      } catch (error) {
        setMessage('❌ Erro ao deletar produto');
        console.error(error);
      }
    }
  };

  return (
    <div className="admin-products">
      {/* HEADER */}
      <div className="admin-header">
        <h2>🛍️ Gerenciar Produtos</h2>
        <div className="header-stats">
          <div className="stat">
            <span className="stat-label">Total</span>
            <span className="stat-value">{products.length}</span>
          </div>
          <div className="stat">
            <span className="stat-label">Baixo Estoque</span>
            <span className="stat-value" style={{ color: '#f59e0b' }}>{lowStockCount}</span>
          </div>
          <div className="stat">
            <span className="stat-label">Sem Estoque</span>
            <span className="stat-value" style={{ color: '#ef4444' }}>{outOfStockCount}</span>
          </div>
        </div>
      </div>

      {/* MENSAGEM DE FEEDBACK */}
      {message && <div className={`admin-message ${message.includes('✅') ? 'success' : 'error'}`}>{message}</div>}

      {/* FILTROS E BUSCA */}
      <div className="filters-section">
        <div className="search-box">
          <input
            type="text"
            placeholder="🔍 Buscar produto..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>

        <select
          value={filterCategory}
          onChange={(e) => setFilterCategory(e.target.value)}
          className="filter-select"
        >
          <option value="">📁 Todas as categorias</option>
          {categories.map(cat => (
            <option key={cat.id} value={cat.id}>{cat.name}</option>
          ))}
        </select>

        <button onClick={() => setShowNewForm(!showNewForm)} className="btn-new">
          {showNewForm ? '❌ Cancelar' : '➕ Novo Produto'}
        </button>

        <div className="results-info">
          Mostrando <strong>{filteredProducts.length}</strong> de <strong>{products.length}</strong> produtos
        </div>
      </div>

      {/* FORMULÁRIO NOVO PRODUTO */}
      {showNewForm && (
        <div className="new-product-form">
          <div className="form-row">
            <div className="form-group">
              <label>Nome do Produto *</label>
              <input
                type="text"
                placeholder="Ex: Arroz 5kg"
                value={newProduct.name}
                onChange={(e) => setNewProduct({...newProduct, name: e.target.value})}
                className="form-input"
              />
            </div>
            <div className="form-group">
              <label>Preço *</label>
              <input
                type="number"
                placeholder="Ex: 25.50"
                value={newProduct.price}
                onChange={(e) => setNewProduct({...newProduct, price: e.target.value})}
                className="form-input"
                step="0.01"
              />
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label>Unidade *</label>
              <input
                type="text"
                placeholder="Ex: kg, L, un"
                value={newProduct.unit}
                onChange={(e) => setNewProduct({...newProduct, unit: e.target.value})}
                className="form-input"
              />
            </div>
            <div className="form-group">
              <label>Categoria *</label>
              <select
                value={newProduct.category_id}
                onChange={(e) => setNewProduct({...newProduct, category_id: e.target.value})}
                className="form-input"
              >
                <option value="">Selecione uma categoria</option>
                {categories.map(cat => (
                  <option key={cat.id} value={cat.id}>{cat.name}</option>
                ))}
              </select>
            </div>
          </div>

          <div className="form-row">
            <div className="form-group">
              <label>Estoque</label>
              <input
                type="number"
                placeholder="Ex: 50"
                value={newProduct.estoque}
                onChange={(e) => setNewProduct({...newProduct, estoque: e.target.value})}
                className="form-input"
              />
            </div>
            <div className="form-group">
              <label>Imagem</label>
              <input
                type="file"
                accept="image/*"
                onChange={(e) => setImageFile(e.target.files[0])}
                className="form-input"
              />
            </div>
          </div>

          <div className="form-buttons">
            <button onClick={createProduct} className="btn-save">💾 Criar Produto</button>
            <button onClick={() => setShowNewForm(false)} className="btn-cancel">❌ Cancelar</button>
          </div>
        </div>
      )}

      {/* LISTA DE PRODUTOS */}
      <div className="products-container">
        {filteredProducts.length === 0 ? (
          <div className="empty-state">
            <p>📭 Nenhum produto encontrado</p>
          </div>
        ) : (
          <div className="products-grid">
            {filteredProducts.map(product => {
              const stockStatus = getStockStatus(product.estoque);
              return (
                <div key={product.id} className="product-card">
                  {editingId === product.id ? (
                    // MODAL DE EDIÇÃO
                    <div className="edit-modal">
                      <div className="modal-header">
                        <h3>Editar Produto</h3>
                        <button className="close-modal" onClick={() => setEditingId(null)}>✕</button>
                      </div>

                      <div className="edit-form">
                        <div className="form-row">
                          <div className="form-group">
                            <label>Nome</label>
                            <input
                              type="text"
                              value={editData.name}
                              onChange={(e) => setEditData({...editData, name: e.target.value})}
                              className="form-input"
                            />
                          </div>
                          <div className="form-group">
                            <label>Preço</label>
                            <input
                              type="number"
                              value={editData.price}
                              onChange={(e) => setEditData({...editData, price: e.target.value})}
                              className="form-input"
                              step="0.01"
                            />
                          </div>
                        </div>

                        <div className="form-row">
                          <div className="form-group">
                            <label>Unidade</label>
                            <input
                              type="text"
                              value={editData.unit}
                              onChange={(e) => setEditData({...editData, unit: e.target.value})}
                              className="form-input"
                            />
                          </div>
                          <div className="form-group">
                            <label>Categoria</label>
                            <select
                              value={editData.category_id}
                              onChange={(e) => setEditData({...editData, category_id: e.target.value})}
                              className="form-input"
                            >
                              {categories.map(cat => (
                                <option key={cat.id} value={cat.id}>{cat.name}</option>
                              ))}
                            </select>
                          </div>
                        </div>

                        <div className="form-row">
                          <div className="form-group">
                            <label>Estoque</label>
                            <input
                              type="number"
                              value={editData.estoque}
                              onChange={(e) => setEditData({...editData, estoque: e.target.value})}
                              className="form-input"
                            />
                          </div>
                        </div>

                        <div className="form-buttons">
                          <button onClick={saveEdit} className="btn-save">💾 Salvar Alterações</button>
                          <button onClick={() => setEditingId(null)} className="btn-cancel">❌ Cancelar</button>
                        </div>
                      </div>
                    </div>
                  ) : (
                    // CARD DE PRODUTO
                    <div className="product-display">
                      {product.image_url && (
                        <div className="product-image">
                          <img src={`http://localhost:3001${product.image_url}`} alt={product.name} />
                        </div>
                      )}

                      <div className="product-info">
                        <h3 className="product-name">{product.name}</h3>
                        <p className="product-category">{getCategoryName(product.category_id)}</p>

                        <div className="product-meta">
                          <span className="price">R$ {parseFloat(product.price).toFixed(2)}</span>
                          <span className="unit">{product.unit}</span>
                        </div>

                        <div className="stock-badge" style={{ borderColor: stockStatus.color }}>
                          <span>{stockStatus.icon}</span>
                          <span>{product.estoque} un</span>
                          <span>{stockStatus.text}</span>
                        </div>

                        <div className="product-actions">
                          <button onClick={() => startEdit(product)} className="btn-edit">✏️ Editar</button>
                          <button onClick={() => deleteProduct(product.id)} className="btn-delete">🗑️ Deletar</button>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

export default AdminProducts;
